// Small deterministic 2x3 RGB images generated for runtime-only decode tests.
export const IMAGE_FIXTURES = Object.freeze({
  jpeg: {
    mime: "image/jpeg",
    base64: "",
  },
  png: {
    mime: "image/png",
    base64: "iVBORw0KGgoAAAANSUhEUgAAAAIAAAADCAIAAAA2iEnWAAAAFElEQVR4nGPcIhfFwMDAxMDAgKAAFvIBMiXK39YAAAAASUVORK5CYII=",
  },
  webp: {
    mime: "image/webp",
    base64: "UklGRjQAAABXRUJQVlA4ICgAAABwAQCdASoCAAMAAUAmJaACdAGIQAD+8UgVy/9pZ//2Vj//SsfwqAAA",
  },
  jpegExif: {
    mime: "image/jpeg",
    base64: "",
  },
  apng: {
    mime: "image/png",
    base64: "iVBORw0KGgoAAAANSUhEUgAAAAIAAAADCAYAAAC56t6BAAAACGFjVEwAAAACAAAAAPONk3AAAAAaZmNUTAAAAAAAAAACAAAAAwAAAAAAAAAAAAEACgIAY5llagAAABZJREFUeJxj/M/A8J+BgYGBiQEK4AwAMTsCBO8eg5EAAAAaZmNUTAAAAAEAAAACAAAAAwAAAAAAAAAAAAEACgIA+OqPvgAAABpmZEFUAAAAAnicY2Rg+P+fgYGBgYkBCuAMAC89AgQu2MLbAAAAAElFTkSuQmCC",
  },
  animatedWebp: {
    mime: "image/webp",
    base64: "UklGRsQAAABXRUJQVlA4WAoAAAACAAAAAQAAAgAAQU5JTQYAAAAAAAAAAABBTk1GSgAAAAAAAAAAAAEAAAIAAGQAAAJWUDggMgAAADABAJ0BKgIAAwABQCYloAADcAD+8ut///mwP/bz/wR6Af//0uD//pcH//S4P/SkAAAAQU5NRkYAAAAAAAAAAAABAAACAABkAAAAVlA4IC4AAAA0AQCdASoCAAMAAAAmJaAAA3AA/vtV4///S4P/+lwf/9Lg/9Lg//rV5Vesq6AA",
  },
});

export function fixtureBytes(format) {
  const fixture = IMAGE_FIXTURES[format];
  if (!fixture) throw new Error("Unknown image fixture");
  const binary = atob(fixture.base64);
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}
